CREATE TABLE registry_trust_versions(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,version TEXT NOT NULL,digest TEXT NOT NULL,trust_json TEXT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,version));
ALTER TABLE registry_trust_versions ENABLE ROW LEVEL SECURITY; ALTER TABLE registry_trust_versions FORCE ROW LEVEL SECURITY; CREATE POLICY scope_isolation ON registry_trust_versions USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
CREATE TRIGGER immutable_registry_trust BEFORE UPDATE OR DELETE ON registry_trust_versions FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
CREATE TABLE registry_control(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,state_json TEXT NOT NULL CHECK(octet_length(state_json)<=65536),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid));
CREATE TABLE registry_generations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,digest TEXT NOT NULL,version TEXT NOT NULL,generation_json TEXT NOT NULL CHECK(octet_length(generation_json)<=262144),pack_json TEXT NOT NULL CHECK(octet_length(pack_json)<=3145728),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,digest),UNIQUE(organization_id,tenant_id,project_id,agent_uid,version));
CREATE TABLE registry_operations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,actor_id TEXT NOT NULL,operation_id TEXT NOT NULL,command_digest TEXT NOT NULL,receipt_json TEXT NOT NULL CHECK(octet_length(receipt_json)<=262144),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,actor_id,operation_id));
CREATE TABLE registry_session_bindings(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,session_key TEXT NOT NULL,lifetime TEXT NOT NULL,digest TEXT,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,session_key,lifetime));
INSERT INTO registry_session_bindings SELECT organization_id,tenant_id,project_id,agent_uid,session_id,lifetime,NULL FROM session_heads;
